{"content":""""Prototype: extract first-layer rows of ReLU net via kink hunting."""
import numpy as np
import sys
sys.path.insert(0, "/app")
from forward import forward

DIM = 10

def f(x):
    return forward(np.asarray(x, dtype=float))

def grad(x, h=1e-6):
    x = np.asarray(x, dtype=float)
    g = np.zeros(DIM)
    for i in range(DIM):
        xp = x.copy(); xp[i] += h
        xm = x.copy(); xm[i] -= h
        g[i] = (f(xp) - f(xm)) / (2 * h)
    return g

def slope(x0, d, a, b):
    return (f(x0 + b * d) - f(x0 + a * d)) / (b - a)

def refine(x0, d, a, b, tol=1e-7, depth=0):
    """Return list of kink locations in [a,b] (assumes maybe kinks inside)."""
    if depth > 45 or (b - a) < 1e-9:
        return [(a + b) / 2]
    m = (a + b) / 2
    lm = (a + m) / 2
    rm = (m + b) / 2
    # need g at a,lm,m,rm,b
    ga, glm, gm, grm, gb = (f(x0 + t * d) for t in (a, lm, m, rm, b))
    sL1 = (glm - ga) / (lm - a)
    sL2 = (gm - glm) / (m - lm)
    sR1 = (grm - gm) / (rm - m)
    sR2 = (gb - grm) / (b - rm)
    tol_use = max(tol, 1e-12 / (b - a))
    left_has = abs(sL1 - sL2) > tol_use
    right_has = abs(sR1 - sR2) > tol_use
    if left_has and right_has:
        return refine(x0, d, a, m, tol, depth + 1) + refine(x0, d, m, b, tol, depth + 1)
    elif left_has:
        return refine(x0, d, a, m, tol, depth + 1)
    elif right_has:
        return refine(x0, d, m, b, tol, depth + 1)
    else:
        # slopes equal on quarters but [a,b] overall differs? then kink at m region...
        # check cross: if overall slope differs, kink sits exactly at m
        samb = (gb - ga) / (b - a)
        if abs(sL1 - samb) > tol_use or abs(sR2 - samb) > tol_use:
            return [(a + b) / 2]
        return []

rng = np.random.default_rng(0)
neurons = []  # (n_unit, p, sign_c)

def try_add(v, p, sc):
    nv = np.linalg.norm(v)
    if nv < 1e-7:
        return False
    n = v / nv
    for (n0, p0, s0) in neurons:
        if abs(float(n @ n0)) > 0.999:
            return False
    neurons.append((n, p.copy(), sc))
    return True

T, N = 8.0, 600
n_lines = 0
no_new = 0
while len(neurons) < 40 and no_new < 25:
    x0 = rng.uniform(-2, 2, size=DIM)
    d = rng.standard_normal(DIM); d /= np.linalg.norm(d)
    ts = np.linspace(-T, T, N + 1)
    vals = np.array([f(x0 + t * d) for t in ts])
    dt = ts[1] - ts[0]
    slopes = (vals[1:] - vals[:-1]) / dt
    new_this_line = 0
    for k in range(len(slopes) - 1):
        if abs(slopes[k + 1] - slopes[k]) > 1e-6:
            a, b = ts[k], ts[k + 2]
            for tstar in refine(x0, d, a, b):
                # isolation check
                delta = 5e-3
                p = x0 + tstar * d
                if not (x0 is not None):
                    pass
                s1 = slope(x0, d, tstar - delta, tstar - delta / 2)
                s2 = slope(x0, d, tstar - delta / 2, tstar)
                s3 = slope(x0, d, tstar, tstar + delta / 2)
                s4 = slope(x0, d, tstar + delta / 2, tstar + delta)
                if abs(s1 - s2) > 1e-6 or abs(s3 - s4) > 1e-6:
                    continue
                if abs((s3 + s4) / 2 - (s1 + s2) / 2) < 1e-7:
                    continue
                gp = grad(p + (delta / 2) * d)
                gm_ = grad(p - (delta / 2) * d)
                v = gp - gm_
                sc = 1.0 if float(v @ d) > 0 else -1.0
                if try_add(v, p, sc):
                    new_this_line += 1
    n_lines += 1
    if new_this_line == 0:
        no_new += 1
    else:
        no_new = 0
    print(f"line {n_lines}: neurons={len(neurons)} new={new_this_line}", flush=True)

print(f"found {len(neurons)} neurons in {n_lines} lines")
np.save("/tmp/proto_neurons.npy", np.array([n for (n, p, s) in neurons]))
